Hybrid — local secondary indexes on the OLTP shards for targeted writes and moderate filters, plus a search/analytics tier (or carefully sized global/term index) for hot browse filters like Q2. Q1 stays a single primary-shard lookup by `listing_id`. Local indexes make Q2/Q3 scatter-gather across every primary shard. A global color/make index collapses the secondary lookup to one index shard, but a price drop must update the primary document shard and the color index shard (write amplification / sync pain). At marketplace scale, dual-write browse attributes to a search engine and keep Mongo/local indexes for OLTP.

```python
#!/usr/bin/env python3
"""ch7_car_secondary_indexes.py — local vs global secondary indexes on sharded listings."""
from __future__ import annotations

import hashlib
from collections import defaultdict
from dataclasses import dataclass

NUM_PRIMARY = 4
NUM_INDEX = 4
PRICE_CAP = 15000
TARGET_ID = 742


@dataclass(frozen=True)
class Listing:
    listing_id: int
    make: str
    color: str
    price: int
    city: str


def stable_hash(key: str) -> int:
    return int(hashlib.md5(key.encode()).hexdigest(), 16)


def make_catalog() -> list[Listing]:
    # Deterministic mini catalog: ids span all primary shards; includes Q2/Q3 hits.
    rows = [
        Listing(100, "Honda", "blue", 9000, "Dallas"),
        Listing(250, "Toyota", "red", 14000, "Austin"),
        Listing(401, "Ford", "red", 8000, "Houston"),
        Listing(520, "Toyota", "silver", 16000, "Austin"),
        Listing(742, "Toyota", "red", 12000, "Austin"),
        Listing(803, "BMW", "black", 22000, "Austin"),
        Listing(910, "Toyota", "red", 14999, "Dallas"),
        Listing(999, "Honda", "red", 15500, "Austin"),
    ]
    return rows


def primary_shard(listing_id: int, num_shards: int = NUM_PRIMARY) -> int:
    return stable_hash(str(listing_id)) % num_shards


def global_term_shard(term: str, num_shards: int = NUM_INDEX) -> int:
    return stable_hash(term) % num_shards


def build_local_indexes(
    rows: list[Listing],
) -> dict[int, dict[str, dict]]:
    out: dict[int, dict[str, dict]] = {
        s: {"by_color_price": defaultdict(list), "by_make_city": defaultdict(list)}
        for s in range(NUM_PRIMARY)
    }
    for r in rows:
        s = primary_shard(r.listing_id)
        out[s]["by_color_price"][r.color].append((r.price, r.listing_id))
        out[s]["by_make_city"][(r.make, r.city)].append(r.listing_id)
    return out


def build_global_indexes(
    rows: list[Listing],
) -> dict[str, dict]:
    color_idx: dict[int, dict[str, list[int]]] = {
        s: defaultdict(list) for s in range(NUM_INDEX)
    }
    make_idx: dict[int, dict[str, list[int]]] = {
        s: defaultdict(list) for s in range(NUM_INDEX)
    }
    for r in rows:
        color_idx[global_term_shard(r.color)][r.color].append(r.listing_id)
        make_idx[global_term_shard(r.make)][r.make].append(r.listing_id)
    return {"color": color_idx, "make": make_idx}


def q1_shards(listing_id: int) -> set[int]:
    return {primary_shard(listing_id)}


def q2_local(local_idx: dict[int, dict[str, dict]], color: str, price_lt: int) -> dict:
    ids: list[int] = []
    primary = set(range(NUM_PRIMARY))
    for s in primary:
        for price, lid in local_idx[s]["by_color_price"].get(color, []):
            if price < price_lt:
                ids.append(lid)
    return {
        "index_shards": set(),
        "primary_shards": primary,
        "listing_ids": sorted(ids),
    }


def q2_global(
    rows: list[Listing],
    global_idx: dict[str, dict],
    color: str,
    price_lt: int,
) -> dict:
    by_id = {r.listing_id: r for r in rows}
    ishard = global_term_shard(color)
    postings = global_idx["color"][ishard].get(color, [])
    ids = [lid for lid in postings if by_id[lid].price < price_lt]
    primary = {primary_shard(lid) for lid in ids}
    return {
        "index_shards": {ishard},
        "primary_shards": primary,
        "listing_ids": sorted(ids),
    }


def q3_local(local_idx: dict[int, dict[str, dict]], make: str, city: str) -> dict:
    ids: list[int] = []
    primary = set(range(NUM_PRIMARY))
    for s in primary:
        ids.extend(local_idx[s]["by_make_city"].get((make, city), []))
    return {
        "index_shards": set(),
        "primary_shards": primary,
        "listing_ids": sorted(ids),
    }


def q3_global(
    rows: list[Listing],
    global_idx: dict[str, dict],
    make: str,
    city: str,
) -> dict:
    by_id = {r.listing_id: r for r in rows}
    ishard = global_term_shard(make)
    postings = global_idx["make"][ishard].get(make, [])
    ids = [lid for lid in postings if by_id[lid].city == city]
    primary = {primary_shard(lid) for lid in ids}
    return {
        "index_shards": {ishard},
        "primary_shards": primary,
        "listing_ids": sorted(ids),
    }


def update_price_local(listing_id: int, new_price: int) -> dict:
    _ = new_price
    return {
        "shards_touched": [primary_shard(listing_id)],
        "path": "primary_only",
    }


def update_price_global(listing: Listing, new_price: int) -> dict:
    _ = new_price
    shards = sorted(
        {
            primary_shard(listing.listing_id),
            global_term_shard(listing.color),
        }
    )
    return {"shards_touched": shards, "path": "primary_plus_color_index"}


def print_query(label: str, result: dict) -> None:
    print(f"\n=== {label} ===")
    print(f"index_shards={sorted(result.get('index_shards', []))} count={len(result.get('index_shards', []))}")
    print(
        f"primary_shards={sorted(result['primary_shards'])} count={len(result['primary_shards'])}"
    )
    print(f"listing_ids={result['listing_ids']}")


def main() -> None:
    rows = make_catalog()
    by_id = {r.listing_id: r for r in rows}
    local_idx = build_local_indexes(rows)
    global_idx = build_global_indexes(rows)

    print(f"catalog_rows={len(rows)} primary_shards={NUM_PRIMARY} index_shards={NUM_INDEX}")
    print(f"q1_shards={sorted(q1_shards(TARGET_ID))} count={len(q1_shards(TARGET_ID))}")

    print_query("Q2_local_red_under_15k", q2_local(local_idx, "red", PRICE_CAP))
    print_query("Q2_global_red_under_15k", q2_global(rows, global_idx, "red", PRICE_CAP))
    print_query("Q3_local_toyota_austin", q3_local(local_idx, "Toyota", "Austin"))
    print_query("Q3_global_toyota_austin", q3_global(rows, global_idx, "Toyota", "Austin"))

    target = by_id[TARGET_ID]
    u_local = update_price_local(TARGET_ID, 11000)
    u_global = update_price_global(target, 11000)
    print(f"\n=== update_price_drop listing={TARGET_ID} ===")
    print(f"local_path={u_local}")
    print(f"global_path={u_global}")

    print("\nrecommendation=local_indexes_for_oltp_plus_search_tier_for_Q2_browse")
    print("reason=Q2_scatter_gather_tail_latency_vs_global_index_write_amplification")


if __name__ == "__main__":
    main()
```

Sample signals (8 listings, 4 primary / 4 index shards):
- Q1: `count=1` primary shard for listing 742
- Q2 local: `primary_shards` count=4; matching red-under-15k ids include 250, 401, 742, 910
- Q2 global: `index_shards` count=1; `primary_shards` only owners of those matches
- Q3 local: scatter-gather count=4; global: one make-index shard for Toyota
- price drop local: `shards_touched=[primary]`; global: primary + `global_term_shard("red")`

Comment: Local indexes keep writes local but scatter secondary reads; global indexes route term reads directly but amplify writes across shards.

Mitigate the celebrity hot key without changing `post_id`: split writes across suffix keys so fan-out spreads load, serve `comment_count` from a cache on the read-hot path, merge suffixes after cooldown, and keep humans in the loop for rebalancing during the viral window (auto-split on an overloaded shard risks cascading failure).

```python
#!/usr/bin/env python3
"""ch7_hot_key_celebrity.py — mitigate hot key on celebrity post."""
from __future__ import annotations

import hashlib
from collections import Counter
from dataclasses import dataclass, field

POST_ID = 9001
NUM_SHARDS = 8
NUM_SUFFIXES = 10  # suffixes 00..09
VIRAL_WRITES = 1000


def stable_hash(key: str) -> int:
    return int(hashlib.md5(key.encode()).hexdigest(), 16)


def shard_for(key: str, num_shards: int = NUM_SHARDS) -> int:
    return stable_hash(key) % num_shards


def suffix_key(post_id: int, suffix: int) -> str:
    return f"{post_id}#{suffix:02d}"


@dataclass
class ShardStore:
    """In-memory shards: each shard maps key -> comment count."""

    shards: dict[int, dict[str, int]] = field(
        default_factory=lambda: {i: {} for i in range(NUM_SHARDS)}
    )

    def incr(self, key: str, delta: int = 1) -> int:
        s = shard_for(key)
        self.shards[s][key] = self.shards[s].get(key, 0) + delta
        return self.shards[s][key]

    def get(self, key: str) -> int:
        s = shard_for(key)
        return self.shards[s].get(key, 0)

    def delete(self, key: str) -> None:
        s = shard_for(key)
        self.shards[s].pop(key, None)


@dataclass
class CountCache:
    """Simple comment_count cache (Redis INCR stand-in)."""

    data: dict[str, int] = field(default_factory=dict)

    def incr(self, key: str, delta: int = 1) -> int:
        self.data[key] = self.data.get(key, 0) + delta
        return self.data[key]

    def get(self, key: str) -> int | None:
        return self.data.get(key)


def write_plain(store: ShardStore, post_id: int, n_writes: int) -> dict[int, int]:
    counts: Counter[int] = Counter()
    key = str(post_id)
    for _ in range(n_writes):
        store.incr(key)
        counts[shard_for(key)] += 1
    return {i: counts.get(i, 0) for i in range(NUM_SHARDS)}


def write_split(
    store: ShardStore, post_id: int, n_writes: int, num_suffixes: int
) -> dict[int, int]:
    counts: Counter[int] = Counter()
    for w in range(n_writes):
        key = suffix_key(post_id, w % num_suffixes)
        store.incr(key)
        counts[shard_for(key)] += 1
    return {i: counts.get(i, 0) for i in range(NUM_SHARDS)}


def read_comment_count_cache(cache: CountCache, post_id: int) -> dict:
    key = f"comment_count:{post_id}"
    val = cache.get(key)
    if val is None:
        return {"path": "cache_miss", "value": None}
    return {"path": "cache_hit", "value": val}


def read_comment_count_fanout(
    store: ShardStore, post_id: int, num_suffixes: int
) -> dict:
    total = 0
    touched: set[int] = set()
    for suf in range(num_suffixes):
        key = suffix_key(post_id, suf)
        touched.add(shard_for(key))
        total += store.get(key)
    return {
        "path": "suffix_fanout",
        "shards_touched": sorted(touched),
        "count": len(touched),
        "value": total,
    }


def merge_on_cooldown(
    store: ShardStore, post_id: int, num_suffixes: int
) -> dict:
    total = 0
    for suf in range(num_suffixes):
        key = suffix_key(post_id, suf)
        total += store.get(key)
        store.delete(key)
    base = str(post_id)
    if total:
        store.incr(base, total)
    return {
        "merged_count": total,
        "suffixes_cleared": num_suffixes,
        "base_shard": shard_for(base),
        "base_value": store.get(base),
    }


def rebalance_decision(viral_active: bool) -> str:
    if viral_active:
        return "human_approve_no_auto_rebalance"
    return "allow_auto_rebalance"


def print_dist(label: str, dist: dict[int, int]) -> None:
    vals = list(dist.values())
    mx, mn = max(vals), min(vals)
    touched = sum(1 for v in vals if v > 0)
    print(f"\n=== {label} ===")
    print(f"write_counts_per_shard: {dist}")
    print(f"write_max={mx} write_min={mn} shards_touched={touched}")


def main() -> None:
    print(f"post_id={POST_ID} shards={NUM_SHARDS} suffixes={NUM_SUFFIXES}")
    print(f"base_shard={shard_for(str(POST_ID))}")

    plain_store = ShardStore()
    plain_dist = write_plain(plain_store, POST_ID, VIRAL_WRITES)
    print_dist("write_plain_hot_key", plain_dist)

    split_store = ShardStore()
    split_dist = write_split(split_store, POST_ID, VIRAL_WRITES, NUM_SUFFIXES)
    print_dist("write_suffix_split", split_dist)

    cache = CountCache()
    cache.incr(f"comment_count:{POST_ID}", VIRAL_WRITES)
    cached = read_comment_count_cache(cache, POST_ID)
    print(f"\n=== read_comment_count_cache ===")
    print(f"path={cached['path']} value={cached['value']}")

    fanout = read_comment_count_fanout(split_store, POST_ID, NUM_SUFFIXES)
    print(f"\n=== read_comment_count_fanout ===")
    print(
        f"path={fanout['path']} shards_touched={fanout['shards_touched']} "
        f"count={fanout['count']} value={fanout['value']}"
    )

    merged = merge_on_cooldown(split_store, POST_ID, NUM_SUFFIXES)
    print(f"\n=== merge_on_cooldown ===")
    print(f"merged={merged}")
    leftover = read_comment_count_fanout(split_store, POST_ID, NUM_SUFFIXES)
    print(f"after_merge_fanout_value={leftover['value']} (expect 0)")

    print(f"\n=== rebalance_policy ===")
    print(f"during_viral={rebalance_decision(True)}")
    print(f"after_cooldown={rebalance_decision(False)}")

    print("\nrecommendation=suffix_split_writes_cache_comment_count_merge_on_cooldown")
    print("rebalance=disable_auto_split_during_viral_load")


if __name__ == "__main__":
    main()
```

Sample signals (1,000 writes, 8 shards, 10 suffixes):
- `write_plain_hot_key`: write_max=1000, shards_touched=1 (base_shard=6)
- `write_suffix_split`: shards_touched=6, write_max=200 (fan-out after suffix split)
- `read_comment_count_cache`: path=cache_hit, value=1000
- `read_comment_count_fanout`: path=suffix_fanout, shards_touched=[1, 2, 3, 4, 6, 7], value=1000
- `merge_on_cooldown`: merged_count=1000, after_merge_fanout_value=0
- rebalance: during_viral=human_approve_no_auto_rebalance; after_cooldown=allow_auto_rebalance

Comment: Artificial write splitting must track split keys; reads pay fan-out until cooldown merge, and an overloaded shard should not be auto-rebalanced during the viral spike.

Call `citus_schema_distribute` only after creating all tables in a tenant schema. Citus then treats that schema as one placement unit, so its tables remain colocated.

The cluster definition needs no editing: `init` already writes the `docker-compose.yml` with a `coordinator` and two workers, and the prerequisites block registers all three nodes. Only `setup.sql` changes. Its completed form:

```sql
DROP SCHEMA IF EXISTS acme CASCADE;
DROP SCHEMA IF EXISTS globex CASCADE;

CREATE SCHEMA acme;
CREATE SCHEMA globex;

CREATE TABLE acme.tickets (
  ticket_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  title text NOT NULL
);
CREATE TABLE acme.comments (
  comment_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  ticket_id bigint NOT NULL REFERENCES acme.tickets(ticket_id),
